6	/**
7	 * Verify that the number of applied Drizzle migrations in the database
8	 * matches the expected count from the local migration journal.
9	 *
10	 * In production this function never throws — it logs an error and reports
11	 * to Sentry so the team gets ops visibility without a hard failure.
12	 */
13	export async function assertMigrationsUpToDate(): Promise<void> {
14	  try {
15	    const result = await db.execute<{ count: string }>(
16	      sql`SELECT COUNT(*)::text AS count FROM drizzle.__drizzle_migrations`,
17	    );
18	
19	    const appliedCount = Number.parseInt(result.rows[0]?.count ?? '0', 10);
20	
21	    if (appliedCount !== MIGRATION_COUNT) {
22	      const message = `[db-health] Migration count mismatch: ${appliedCount} applied vs ${MIGRATION_COUNT} expected`;
23	      console.error(message);
24	
25	      try {
26	        Sentry.captureMessage(message, 'error');
27	      } catch {
28	        // Sentry may not be initialized — swallow silently
29	      }
30	    }
31	  } catch (err) {
32	    if (process.env.NODE_ENV === 'production') {
33	      console.error('[db-health] Failed to check migration count:', err);
34	      try {
35	        Sentry.captureException(err);
36	      } catch {
37	        // Sentry may not be initialized — swallow silently
38	      }
39	      return;
40	    }
41	    // In non-production environments, let the caller know
42	    throw err;
43	  }
44	}
