1	/**
2	 * In-memory Circuit Breaker for external API calls.
3	 *
4	 * States:
5	 *   CLOSED    → requests flow through normally; failures are tracked
6	 *   OPEN      → requests are immediately rejected with CircuitOpenError
7	 *   HALF_OPEN → a limited number of probe requests are allowed through
8	 *
9	 * Transitions:
10	 *   CLOSED → OPEN      after `failureThreshold` failures within `failureWindowMs`
11	 *   OPEN → HALF_OPEN   after `resetTimeoutMs` elapses
12	 *   HALF_OPEN → CLOSED  after `successThreshold` consecutive successes
13	 *   HALF_OPEN → OPEN    on any failure during the probe phase
14	 */
15	
16	// ─── Types ────────────────────────────────────────────────────────────────────
17	
18	type CircuitState = 'CLOSED' | 'OPEN' | 'HALF_OPEN';
19	
20	export interface CircuitBreakerOptions {
21	  /** Identifier used in log messages. */
22	  name: string;
23	  /** Number of failures within `failureWindowMs` that trip the breaker. Default 5. */
24	  failureThreshold?: number;
25	  /** Rolling window (ms) in which failures are counted. Default 60 000 (60 s). */
26	  failureWindowMs?: number;
27	  /** How long (ms) to stay OPEN before transitioning to HALF_OPEN. Default 30 000 (30 s). */
28	  resetTimeoutMs?: number;
29	  /** Consecutive successes in HALF_OPEN needed to close the breaker. Default 2. */
30	  successThreshold?: number;
31	}
32	
33	// ─── Error ────────────────────────────────────────────────────────────────────
34	
35	export class CircuitOpenError extends Error {
36	  constructor(name: string) {
37	    super(`Circuit breaker "${name}" is OPEN — request rejected`);
38	    this.name = 'CircuitOpenError';
39	  }
40	}
41	
42	// ─── Circuit Breaker ──────────────────────────────────────────────────────────
43	
44	export class CircuitBreaker {
45	  private readonly cbName: string;
46	  private readonly failureThreshold: number;
47	  private readonly failureWindowMs: number;
48	  private readonly resetTimeoutMs: number;
49	  private readonly successThreshold: number;
50	
51	  private state: CircuitState = 'CLOSED';
52	  private failures: number[] = []; // timestamps of recent failures
53	  private lastFailureTime = 0;
54	  private halfOpenSuccesses = 0;
55	
56	  constructor(opts: CircuitBreakerOptions) {
57	    this.cbName = opts.name;
58	    this.failureThreshold = opts.failureThreshold ?? 5;
59	    this.failureWindowMs = opts.failureWindowMs ?? 60_000;
60	    this.resetTimeoutMs = opts.resetTimeoutMs ?? 30_000;
61	    this.successThreshold = opts.successThreshold ?? 2;
62	  }
63	
64	  /**
65	   * Execute `fn` through the circuit breaker.
66	   *
67	   * - If the breaker is OPEN and the reset timeout has not elapsed,
68	   *   throws `CircuitOpenError` immediately (no call is made).
69	   * - Otherwise, `fn` is invoked and its result / error determines
70	   *   the next state transition.
71	   */
72	  async execute<T>(fn: () => Promise<T>): Promise<T> {
73	    const now = Date.now();
74	
75	    // ── OPEN gate ──────────────────────────────────────────────────────
76	    if (this.state === 'OPEN') {
77	      if (now - this.lastFailureTime >= this.resetTimeoutMs) {
78	        this.transition('HALF_OPEN');
79	      } else {
80	        throw new CircuitOpenError(this.cbName);
81	      }
82	    }
83	
84	    // ── Attempt the call ───────────────────────────────────────────────
85	    try {
86	      const result = await fn();
87	      this.onSuccess();
88	      return result;
89	    } catch (err) {
90	      this.onFailure();
91	      throw err;
92	    }
93	  }
94	
95	  // ── Internal helpers ────────────────────────────────────────────────────
96	
97	  private onSuccess(): void {
98	    if (this.state === 'HALF_OPEN') {
99	      this.halfOpenSuccesses += 1;
100	      if (this.halfOpenSuccesses >= this.successThreshold) {
101	        this.transition('CLOSED');
102	      }
103	    }
104	    // In CLOSED state, successes don't change anything.
105	  }
106	
107	  private onFailure(): void {
108	    const now = Date.now();
109	
110	    if (this.state === 'HALF_OPEN') {
111	      // Any failure in HALF_OPEN immediately re-opens the breaker.
112	      this.lastFailureTime = now;
113	      this.transition('OPEN');
114	      return;
115	    }
116	
117	    // CLOSED — track failures in the rolling window.
118	    this.failures.push(now);
119	    this.failures = this.failures.filter(
120	      (t) => now - t <= this.failureWindowMs,
121	    );
122	
123	    if (this.failures.length >= this.failureThreshold) {
124	      this.lastFailureTime = now;
125	      this.transition('OPEN');
126	    }
127	  }
128	
129	  private transition(next: CircuitState): void {
130	    const prev = this.state;
131	    this.state = next;
132	
133	    if (next === 'CLOSED') {
134	      this.failures = [];
135	      this.halfOpenSuccesses = 0;
136	    }
137	    if (next === 'HALF_OPEN') {
138	      this.halfOpenSuccesses = 0;
139	    }
140	
141	    console.warn(`[CircuitBreaker:${this.cbName}] ${prev} → ${next}`);
142	  }
143	}
144	
145	// ─── Factory ──────────────────────────────────────────────────────────────────
146	
147	const breakers = new Map<string, CircuitBreaker>();
148	
149	/**
150	 * Returns (or creates) a named circuit breaker singleton.
151	 *
152	 * Re-using the same `name` returns the same instance so multiple call sites
153	 * for the same external service share failure counts.
154	 */
155	export function createCircuitBreaker(
156	  opts: CircuitBreakerOptions,
157	): CircuitBreaker {
158	  const existing = breakers.get(opts.name);
159	  if (existing) return existing;
160	  const cb = new CircuitBreaker(opts);
161	  breakers.set(opts.name, cb);
162	  return cb;
163	}
