1	/**
2	 * DB Startup Probe v2 — auto-detects and applies missing columns across ALL tables.
3	 *
4	 * Dynamically reads the Drizzle schema to find every table/column definition,
5	 * queries information_schema.columns for what actually exists in the database,
6	 * and applies ADD COLUMN IF NOT EXISTS for any gaps.
7	 *
8	 * This eliminates the manual column list that caused the signoff-columns outage
9	 * (b7a063c added columns to the Drizzle schema but not the manual probe list).
10	 *
11	 * Safety guarantees:
12	 * - Only ADDS columns, never drops, renames, or modifies
13	 * - Skips tables that don't exist (CREATE TABLE is a migration concern)
14	 * - Skips columns with complex SQL defaults (gen_random_uuid(), now()) since
15	 *   those columns are always created in the initial migration
16	 * - Uses ADD COLUMN IF NOT EXISTS so it is idempotent
17	 */
18	
19	import { safeErrorMessage } from '@/lib/safe-error-message';
20	import { Pool } from '@neondatabase/serverless';
21	import { getTableColumns } from 'drizzle-orm';
22	import type { Column } from 'drizzle-orm';
23	import { getTableConfig } from 'drizzle-orm/pg-core';
24	
25	let probeRan = false;
26	
27	type ProbePool = Pick<InstanceType<typeof Pool>, 'query'>;
28	
29	type EnumBackedColumn = Column & {
30	  enumValues?: readonly string[];
31	};
32	
33	type EnumTypeDefinition = {
34	  typeName: string;
35	  values: readonly string[];
36	};
37	
38	function quoteIdentifier(identifier: string): string {
39	  return `"${identifier.replace(/"/g, '""')}"`;
40	}
41	
42	function quoteQualifiedIdentifier(identifier: string): string {
43	  return identifier.split('.').map(quoteIdentifier).join('.');
44	}
45	
46	function quoteSqlLiteral(value: string): string {
47	  return `'${value.replace(/'/g, "''")}'`;
48	}
49	
50	function getEnumTypeDefinition(col: Column): EnumTypeDefinition | null {
51	  const values = (col as EnumBackedColumn).enumValues;
52	  if (!Array.isArray(values) || values.length === 0) return null;
53	
54	  return {
55	    typeName: col.getSQLType(),
56	    values,
57	  };
58	}
59	
60	function buildCreateEnumTypeSql({
61	  typeName,
62	  values,
63	}: EnumTypeDefinition): string {
64	  const enumValues = values.map(quoteSqlLiteral).join(', ');
65	  return `DO $$ BEGIN CREATE TYPE ${quoteQualifiedIdentifier(typeName)} AS ENUM (${enumValues}); EXCEPTION WHEN duplicate_object THEN NULL; END $$`;
66	}
67	
68	function buildAddEnumValueSql(typeName: string, value: string): string {
69	  return `ALTER TYPE ${quoteQualifiedIdentifier(typeName)} ADD VALUE IF NOT EXISTS ${quoteSqlLiteral(value)}`;
70	}
71	
72	async function ensureEnumType(
73	  pool: ProbePool,
74	  enumType: EnumTypeDefinition,
75	): Promise<void> {
76	  await pool.query(buildCreateEnumTypeSql(enumType));
77	  for (const value of enumType.values) {
78	    await pool.query(buildAddEnumValueSql(enumType.typeName, value));
79	  }
80	}
81	
82	/**
83	 * Convert a Drizzle column definition to an ADD COLUMN SQL fragment.
84	 * Returns null for columns with complex defaults that can't be expressed inline.
85	 */
86	function columnToSqlDefinition(col: Column): string | null {
87	  let sql = col.getSQLType();
88	
89	  // Columns with SQL-expression defaults (gen_random_uuid(), now()) cannot be
90	  // safely expressed in ADD COLUMN. These are always present from initial
91	  // CREATE TABLE, so skipping them is safe.
92	  if (col.hasDefault) {
93	    const d = col.default;
94	    if (d === false) sql += ' DEFAULT FALSE';
95	    else if (d === true) sql += ' DEFAULT TRUE';
96	    else if (typeof d === 'number') sql += ` DEFAULT ${d}`;
97	    else if (typeof d === 'string') sql += ` DEFAULT ${quoteSqlLiteral(d)}`;
98	    else if (Array.isArray(d)) sql += ` DEFAULT '${JSON.stringify(d)}'::jsonb`;
99	    else if (d !== undefined && d !== null) {
100	      // Complex default (SQL expression object) — skip this column
101	      return null;
102	    }
103	  }
104	
105	  return sql;
106	}
107	
108	/**
109	 * Runs a one-time schema drift probe at server startup. Compares the Drizzle
110	 * schema against the actual database and applies any missing columns.
111	 *
112	 * Call from instrumentation.ts `register()` under `NEXT_RUNTIME === 'nodejs'`.
113	 */
114	export async function runSchemaDriftProbe(): Promise<void> {
115	  if (probeRan) return;
116	  // Note: probeRan is set to true only on success (at end of function)
117	  // so that transient failures (e.g. Neon cold-start timeout) don't permanently
118	  // suppress future probe attempts within the same serverless instance.
119	
120	  const url = process.env.DATABASE_URL;
121	  if (!url) {
122	    console.warn('[db-startup-probe] DATABASE_URL not set — skipping probe');
123	    return;
124	  }
125	
126	  // All remaining work is wrapped in a single try-catch so that ANY failure
127	  // (schema import error, Pool construction failure, network error, etc.) is
128	  // caught and logged instead of propagating to the caller as an unhandled
129	  // exception. Without this, errors here bubble up through instrumentation.ts
130	  // register() to Next.js's onRequestError hook, which reports them as fatal
131	  // "Unhandled error" events in Sentry.
132	  let pool: InstanceType<typeof Pool> | null = null;
133	  try {
134	    // Collect all Drizzle table definitions
135	    const schema = await import('./schema/index');
136	    const tables: Array<{
137	      tableName: string;
138	      columns: Record<string, Column>;
139	    }> = [];
