4	 *
5	 * Two structural regressions are made un-shippable:
6	 *
7	 * 1. DERIVE-FROM-URL GUARD — every `findFlightSchoolIdByLocation(...)` call in a
8	 *    route handler must sit next to a session-`orgId` guard. This is the F2
9	 *    pattern: the school id is derived from the URL `locationId`, so the handler
10	 *    MUST also resolve the org from the session and compare them (the codebase
11	 *    convention is `resolveOrgIdFromSession` + `flightSchoolId !== orgId`). A
12	 *    call with no `orgId` reference in its immediate window is flagged.
13	 *
14	 *    A genuinely guard-free site (e.g. a pure resolver helper whose callers
15	 *    enforce the guard) must carry an inline `// tenant-guard-exempt: <reason>`
16	 *    annotation on the call line or the line above it.
17	 *
18	 * 2. HARDCODED ROSTER — frontend source must not ship a hardcoded array of real
19	 *    people (firstName/lastName/email object literals). This prevents another
20	 *    `SEED_STUDENTS` (F1/F4): demo data rendered client-side + PII in the bundle.
21	 *
22	 * Exit 1 on any violation; exit 0 when clean.
23	 */
24	import { readFileSync } from 'node:fs';
25	import { execSync } from 'node:child_process';
26	
27	const DERIVE_FN = 'findFlightSchoolIdByLocation';
28	const EXEMPT = 'tenant-guard-exempt';
29	// Window around the call line in which an `orgId` reference must appear. Wide
30	// enough to span a handler prologue (orgId resolved above) or a guard that
31	// follows a 404/existence check + comment block below the derive call.
32	const BEFORE = 12;
33	const AFTER = 16;
34	
35	function tracked(glob: string): string[] {
36	  return execSync(`git ls-files -- '${glob}'`, { encoding: 'utf8' })
37	    .split('\n')
38	    .filter(Boolean);
39	}
40	
41	const violations: string[] = [];
42	
43	// ── Gate 1: derive-from-URL guard ────────────────────────────────────────────
44	// Only route handlers consume the URL locationId; the repository defines the fn.
45	for (const file of tracked('src/server/routes/*.ts')) {
46	  if (/\.test\.ts$|\.spec\.ts$/.test(file)) continue;
47	  const lines = readFileSync(file, 'utf8').split('\n');
48	  lines.forEach((line, i) => {
49	    if (!line.includes(`${DERIVE_FN}(`)) return;
50	    const windowLines = lines.slice(
51	      Math.max(0, i - BEFORE),
52	      Math.min(lines.length, i + AFTER + 1),
53	    );
54	    const exempt = windowLines.some((l) => l.includes(EXEMPT));
55	    if (exempt) return;
56	    const hasOrgGuard = windowLines.some((l) => /\borgId\b/.test(l));
57	    if (!hasOrgGuard) {
58	      violations.push(
59	        `  ${file}:${i + 1}  ${DERIVE_FN} call with no session orgId guard nearby`,
60	      );
61	    }
62	  });
63	}
64	
65	// ── Gate 2: hardcoded roster / PII in frontend source ────────────────────────
66	const FIRSTNAME = /firstName:\s*['"`]/g;
67	for (const file of tracked('src/components/**/*.tsx')) {
68	  if (/\.test\.tsx$|\.spec\.tsx$|__tests__|__mocks__/.test(file)) continue;
69	  const src = readFileSync(file, 'utf8');
70	  const count = (src.match(FIRSTNAME) ?? []).length;
71	  if (count >= 6) {
72	    violations.push(
73	      `  ${file}  ${count} hardcoded firstName literals — looks like a baked-in roster (SEED_STUDENTS regression)`,
74	    );
75	  }
76	}
