80	  console.error(violations.join('\n'));
81	  console.error(
82	    `\nFix: add resolveOrgIdFromSession + \`flightSchoolId !== orgId\` near each ${DERIVE_FN} call,\n` +
83	      `or annotate a genuinely guard-free resolver with \`// ${EXEMPT}: <reason>\`.\n` +
84	      'Remove hardcoded person rosters from frontend source.\n',
85	  );
86	  process.exit(1);
87	}
