import { users } from '@/lib/schema';
import { type SQL, eq } from 'drizzle-orm';
import { PgDialect } from 'drizzle-orm/pg-core';
import { liveAnd, notDeleted } from '../soft-delete';

const dialect = new PgDialect();
const render = (q: SQL): string => dialect.sqlToQuery(q).sql.toLowerCase();

describe('soft-delete read helper', () => {
  it('notDeleted renders `deleted_at IS NULL`', () => {
    expect(render(notDeleted(users.deletedAt))).toContain(
      '"deleted_at" is null',
    );
  });

  it('liveAnd composes notDeleted with extra predicates', () => {
    const sql = liveAnd(users.deletedAt, eq(users.flightSchoolId, 'org-1'));
    expect(sql).toBeDefined();
    const rendered = render(sql as SQL);
    expect(rendered).toContain('"deleted_at" is null');
    expect(rendered).toContain(' and ');
    expect(rendered).toContain('"flight_school_id"');
  });

  it('liveAnd ignores undefined predicates', () => {
    const sql = liveAnd(users.deletedAt, undefined);
    expect(render(sql as SQL)).toContain('"deleted_at" is null');
  });
});
